import { Table } from '@tale-ui/react/table';
import { TextField } from '@tale-ui/react/text-field';

const people = [
  { id: 'alice', name: 'Alice', email: 'alice@example.com' },
  { id: 'bob', name: 'Bob', email: 'bob@example.com' },
];

export function EditablePeopleTable() {
  return (
    <Table.Root aria-label="Editable people" keyboardNavigationBehavior="tab">
      <Table.Header>
        <Table.Column isRowHeader>Name</Table.Column>
        <Table.Column>Email</Table.Column>
      </Table.Header>
      <Table.Body>
        {people.map((person) => (
          <Table.Row key={person.id} id={person.id}>
            <Table.Cell>{person.name}</Table.Cell>
            <Table.Cell>
              <TextField.Root aria-label={`${person.name} email`} defaultValue={person.email}>
                <TextField.Input />
              </TextField.Root>
            </Table.Cell>
          </Table.Row>
        ))}
      </Table.Body>
    </Table.Root>
  );
}
